// NULL when the variable is not set.
static lstr* narra_env_get(lstr* name) {
  if (memchr(name->data, 0, (size_t)name->len)) return NULL;
  const char* v = getenv(name->data);
  return v ? narra_io_lossy(v, strlen(v)) : NULL;
}

