static lstr L1809 = {-1, 5, "E0976"};
static lstr L1810 = {-1, 133, "the arrow function returns a value that shares its parameter %q, which its function type does not allow; return a copy with copy(...)"};
static lstr L1811 = {-1, 5, "E0976"};
