static lstr L1837 = {-1, 5, "E0981"};
static lstr L1838 = {-1, 59, "typeof %s refers to its own declaration; write the type out"};
static lstr L1839 = {-1, 5, "E0982"};
static lstr L1840 = {-1, 113, "typeof needs a value, but %q is a type; write the type itself, or the name of a const, let, parameter or function"};
static lstr L1841 = {-1, 5, "E0982"};
static lstr L1842 = {-1, 82, "typeof needs a value, but %q is a module; name a const, let, parameter or function"};
static lstr L1843 = {-1, 5, "E0982"};
static lstr L1844 = {-1, 77, "the type of constant %q is not known here; write it as `const %s: Type = ...`"};
static lstr L1845 = {-1, 5, "E0982"};
