static lstr L2912 = {-1, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
static lstr L2913 = {-1, 13, "std/coroutine"};
static lstr L2914 = {-1, 1032, "// std/coroutine: Co.resume runs a generator or a coroutine to its next yield.\012//\012// The compiler turns `Co.resume(mutable g)` into resumeGenerator and\012// `Co.resume(mutable g, input)` into resumeCoroutine, by argument count.\012\012import * as Internal from \"std/internal/coroutine\"\012\012export enum Step<Out> derives Show, Equatable {\012  Yielded(value: Out)\012  Done\012  Panicked(message: string)\012}\012\012export function resumeGenerator<T, effect E>(mutable g: Generator<T> uses E): Step<T> uses E, alloc {\012  return readStep(Internal.next(mutable g))\012}\012\012export function resumeCoroutine<In, Out, effect E>(mutable g: Coroutine<In, Out> uses E, input: In): Step<Out> uses E, alloc {\012  return readStep(Internal.resume(mutable g, input))\012}\012\012// readStep reads the outcome of one resume: a value, the end, or a panic.\012function readStep<T>(next: Option<T>): Step<T> from next uses alloc {\012  if (next is Some(value)) {\012    return Step.Yielded(value)\012  }\012  if (Internal.panicked()) {\012    return Step.Panicked(Internal.panicMessage())\012  }\012  return Step.Done\012}\012"};
static lstr L2915 = {-1, 13, "std/ext/array"};
static lstr L2916 = {-1, 833, "// std/array: helpers over Array. The functions that need the compiler are built in.\012\012import * as Arrays from \"std/array\"\012\012export function map<T, U, effect E>(\012  items: Array<T>,\012  change: (value: T) => U uses E\012): Array<U> uses alloc, E {\012  let result: Array<U> = Arrays.withCapacity(Arrays.length(items))\012  for (const item of items) {\012    Arrays.push(mutable result, change(item))\012  }\012  return result\012}\012\012export function slice<T>(items: Array<T>, start: int, finish: int): Option<Array<T>> uses alloc {\012  // A range outside the array has no slice.\012  if (start < 0 || finish > Arrays.length(items) || start > finish) {\012    return None\012  }\012  let result: Array<T> = Arrays.withCapacity(finish - start)\012  for (let index = start; index < finish; index++) {\012    Arrays.push(mutable result, copy(items[index]))\012  }\012  return Some(result)\012}\012"};
static lstr L2917 = {-1, 13, "std/ext/float"};
static lstr L2918 = {-1, 117, "// std/float: constants of f64. The functions are built into the compiler.\012\012export const PI: f64 = 3.141592653589793\012"};
static lstr L2919 = {-1, 11, "std/ext/int"};
static lstr L2920 = {-1, 915, "// std/int: ordering and division of int. The rest of the functions are built into the compiler.\012\012export function compare(first: int, second: int): Ordering {\012  if (first < second) {\012    return Ordering.Less\012  }\012  if (first > second) {\012    return Ordering.Greater\012  }\012  return Ordering.Equal\012}\012\012export function divmod(dividend: int, divisor: int): Option<#[int, int]> {\012  // A zero divisor has no quotient.\012  if (divisor == 0) {\012    return None\012  }\012  return Some(#[dividend / divisor, dividend % divisor])\012}\012\012export function floorDiv(dividend: int, divisor: int): Option<int> {\012  if (divisor == 0) {\012    return None\012  }\012  const quotient = dividend / divisor\012  const remainder = dividend % divisor\012  // Division truncates toward zero; step down when the signs differ and the division is inexact.\012  if (remainder != 0 && (remainder < 0) != (divisor < 0)) {\012    return Some(quotient - 1)\012  }\012  return Some(quotient)\012}\012"};
