static lstr L2922 = {-1, 231, "// std/string: searching. The rest of the functions are built into the compiler.\012\012import * as Str from \"std/string\"\012\012export function find(text: string, needle: string): Option<int> uses alloc {\012  return Str.indexOf(text, needle)\012}\012"};
